def norm_shape(cells, refl=False):
 pts=[(r-min(x for x,y in cells),c-min(y for x,y in cells)) for r,c in cells]
 return tuple(sorted(pts))
def canonical(cells, allow_reflect=True):
 pts=[(r,c) for r,c in cells]
 arr=[]
 for t in range(8 if allow_reflect else 4):
  trans=[]
  for r,c in pts:
   if t>=4: c=-c
   for _ in range(t%4): r,c=c,-r
   trans.append((r,c))
  mr=min(r for r,c in trans); mc=min(c for r,c in trans)
  arr.append(tuple(sorted((r-mr,c-mc) for r,c in trans)))
 return min(arr)
